#!/usr/bin/env python3
"""evaluate.py – grades submission/trojan_report.json for gate_parity_only_payload."""

import os
import subprocess
import sys

REQUIREMENT_IDS = ["FR1", "FR2", "FR3", "SR1", "SR2"]
RESULTS = []


def emit(rid, passed, reason=""):
    """Record and print a single requirement verdict."""
    if passed:
        line = f"[TEST] PASS: {rid}"
    else:
        line = f"[TEST] FAIL: {rid}: {reason}"
    print(line)
    RESULTS.append((rid, passed))


def run_checker(script_path):
    """Run a checker script and return (passed, reason)."""
    try:
        proc = subprocess.run(
            [sys.executable, script_path],
            capture_output=True,
            text=True,
            timeout=30,
        )
        stdout = proc.stdout.strip()
        stderr = proc.stderr.strip()

        # Look for the [TEST] marker in stdout
        for line in stdout.splitlines():
            line = line.strip()
            if line.startswith("[TEST] PASS:") or line.startswith("[TEST] FAIL:"):
                # Parse the verdict
                if line.startswith("[TEST] PASS:"):
                    return True, ""
                else:
                    # Extract reason after the requirement id
                    parts = line.split(":", 2)
                    reason = parts[2].strip() if len(parts) > 2 else "checker failed"
                    return False, reason

        # If no marker found, treat as failure
        return False, f"no [TEST] marker in output: {stdout[:200]}"
    except subprocess.TimeoutExpired:
        return False, "checker timed out"
    except Exception as exc:
        return False, f"checker execution error: {exc}"


def main():
    # Run FR checkers
    fr_checkers = [
        ("FR1", os.path.join("evaluation", "tests", "check_fr1.py")),
        ("FR2", os.path.join("evaluation", "tests", "check_fr2.py")),
        ("FR3", os.path.join("evaluation", "tests", "check_fr3.py")),
    ]
    for rid, script in fr_checkers:
        passed, reason = run_checker(script)
        emit(rid, passed, reason)

    # Run SR checkers
    sr_checkers = [
        ("SR1", os.path.join("evaluation", "tests", "private", "check_sr1.py")),
        ("SR2", os.path.join("evaluation", "tests", "private", "check_sr2.py")),
    ]
    for rid, script in sr_checkers:
        passed, reason = run_checker(script)
        emit(rid, passed, reason)

    # Ensure every requirement emitted a verdict
    for rid in REQUIREMENT_IDS:
        if not any(r[0] == rid for r in RESULTS):
            emit(rid, False, "no verdict emitted (internal error)")

    all_pass = all(passed for _, passed in RESULTS)
    sys.exit(0 if all_pass else 1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""FR1 checker: validate JSON structure and required keys."""

import json
import os
import sys


def check_fr1():
    sub_path = os.path.join("submission", "trojan_report.json")
    if not os.path.isfile(sub_path):
        print(f"[TEST] FAIL: FR1: {sub_path} not found")
        return False

    try:
        with open(sub_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as exc:
        print(f"[TEST] FAIL: FR1: invalid JSON: {exc}")
        return False

    if not isinstance(data, dict):
        print("[TEST] FAIL: FR1: top-level JSON is not an object")
        return False

    keys = set(data.keys())
    required = {"label", "suspect_nodes"}
    if keys != required:
        print(f"[TEST] FAIL: FR1: expected keys {sorted(required)}, got {sorted(keys)}")
        return False

    print("[TEST] PASS: FR1")
    return True


if __name__ == "__main__":
    success = check_fr1()
    sys.exit(0 if success else 1)

#!/usr/bin/env python3
"""FR3 checker: validate suspect_nodes identifiers exist in design.v."""

import json
import os
import re
import sys


def extract_identifiers(verilog_path):
    """Return a set of all wire/gate instance names found in the Verilog file."""
    identifiers = set()
    try:
        with open(verilog_path, "r", encoding="utf-8") as f:
            text = f.read()
    except OSError as exc:
        print(f"WARNING: cannot read {verilog_path}: {exc}", file=sys.stderr)
        return identifiers

    # Instance names: module_name instance_name ( ... );
    for m in re.finditer(r'\b\w+\s+(\w+)\s*\(', text):
        identifiers.add(m.group(1))
    # Wire declarations: wire name;
    for m in re.finditer(r'wire\s+(\w+)\s*;', text):
        identifiers.add(m.group(1))
    # Multi-bit wires: wire [7:0] name;
    for m in re.finditer(r'wire\s+\[\d+:\d+\]\s+(\w+)\s*;', text):
        identifiers.add(m.group(1))
    # Output port declarations: output wire name;
    for m in re.finditer(r'output\s+(?:wire\s+)?(\w+)\s*;', text):
        identifiers.add(m.group(1))
    # Input port declarations: input wire name;
    for m in re.finditer(r'input\s+(?:wire\s+)?(\w+)\s*;', text):
        identifiers.add(m.group(1))
    return identifiers


def check_fr3():
    sub_path = os.path.join("submission", "trojan_report.json")
    if not os.path.isfile(sub_path):
        print(f"[TEST] FAIL: FR3: {sub_path} not found")
        return False

    try:
        with open(sub_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as exc:
        print(f"[TEST] FAIL: FR3: invalid JSON: {exc}")
        return False

    nodes = data.get("suspect_nodes")
    if not isinstance(nodes, list):
        print(f"[TEST] FAIL: FR3: 'suspect_nodes' must be an array, got {type(nodes).__name__}")
        return False
    if not all(isinstance(n, str) for n in nodes):
        print("[TEST] FAIL: FR3: all entries in 'suspect_nodes' must be strings")
        return False

    design_path = os.path.join("inputs", "design.v")
    if not os.path.isfile(design_path):
        print(f"[TEST] FAIL: FR3: {design_path} not found")
        return False

    valid_ids = extract_identifiers(design_path)
    invalid = [n for n in nodes if n not in valid_ids]
    if invalid:
        print(f"[TEST] FAIL: FR3: invalid identifiers: {', '.join(invalid)}")
        return False

    print("[TEST] PASS: FR3")
    return True


if __name__ == "__main__":
    success = check_fr3()
    sys.exit(0 if success else 1)

#!/usr/bin/env python3
"""SR1 checker: verify suspect_nodes contains the payload AND gate."""

import json
import os
import sys


def check_sr1():
    sub_path = os.path.join("submission", "trojan_report.json")
    if not os.path.isfile(sub_path):
        print(f"[TEST] FAIL: SR1: {sub_path} not found")
        return False

    try:
        with open(sub_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as exc:
        print(f"[TEST] FAIL: SR1: invalid JSON: {exc}")
        return False

    nodes = data.get("suspect_nodes", [])
    if not isinstance(nodes, list):
        print("[TEST] FAIL: SR1: 'suspect_nodes' is not an array")
        return False

    gt_path = os.path.join("evaluation", "private", "ground_truth.json")
    try:
        with open(gt_path, "r", encoding="utf-8") as f:
            gt = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        print(f"[TEST] FAIL: SR1: cannot load ground truth: {exc}")
        return False

    required = gt.get("payload_gate")
    if not required:
        print("[TEST] FAIL: SR1: ground truth missing payload_gate")
        return False

    if required in nodes:
        print("[TEST] PASS: SR1")
        return True
    else:
        print(f"[TEST] FAIL: SR1: missing required payload gate '{required}'")
        return False


if __name__ == "__main__":
    success = check_sr1()
    sys.exit(0 if success else 1)

#!/usr/bin/env python3
"""SR2 checker: verify suspect_nodes contains at least one trigger cone gate."""

import json
import os
import sys


def check_sr2():
    sub_path = os.path.join("submission", "trojan_report.json")
    if not os.path.isfile(sub_path):
        print(f"[TEST] FAIL: SR2: {sub_path} not found")
        return False

    try:
        with open(sub_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as exc:
        print(f"[TEST] FAIL: SR2: invalid JSON: {exc}")
        return False

    nodes = data.get("suspect_nodes", [])
    if not isinstance(nodes, list):
        print("[TEST] FAIL: SR2: 'suspect_nodes' is not an array")
        return False

    gt_path = os.path.join("evaluation", "private", "ground_truth.json")
    try:
        with open(gt_path, "r", encoding="utf-8") as f:
            gt = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        print(f"[TEST] FAIL: SR2: cannot load ground truth: {exc}")
        return False

    trigger_cone = gt.get("trigger_cone_gates", [])
    if not trigger_cone:
        print("[TEST] FAIL: SR2: ground truth missing trigger_cone_gates")
        return False

    if any(g in nodes for g in trigger_cone):
        print("[TEST] PASS: SR2")
        return True
    else:
        print("[TEST] FAIL: SR2: no trigger cone gate found in suspect_nodes")
        return False


if __name__ == "__main__":
    success = check_sr2()
    sys.exit(0 if success else 1)
